function defaultStyleAPI(){return{headingFont:'Inter',bodyFont:'Inter',palette:{background:'#ffffff',surface:'#f4f3f8',text:'#1d1b25',primary:'#6757d9',accent:'#279f86'},locks:{},huemintMode:'transformer',temperature:1.2}}
