function ensureStyleAPI(node){const d=defaultStyleAPI(),old=node.api||{},values=node.values||{};node.api={...d,...old,palette:{...d.palette,...old.palette},locks:{...d.locks,...old.locks}};if(!old.headingFont&&(values.titleFont||values.subtitleFont))node.api.headingFont=values.titleFont||values.subtitleFont;if(!old.bodyFont&&values.bodyFont)node.api.bodyFont=values.bodyFont;for(const role of STYLE_ROLES)if(!old.palette?.[role]&&values[role])node.api.palette[role]=values[role];syncStyleValues(node);return node.api}
