function huemintPayload(api){const matrix=[0,80,88,62,56,80,0,82,48,52,88,82,0,72,64,62,48,72,0,42,56,52,64,42,0].map(String);return{mode:api.huemintMode||'transformer',num_colors:5,temperature:String(Number(api.temperature)||1.2),num_results:api.huemintMode==='diffusion'?5:10,adjacency:matrix,palette:STYLE_ROLES.map(role=>api.locks?.[role]?api.palette[role]:'-')}}
