  const manifesto=original.cloneNode(true);manifesto.querySelector('.nr-gallery')?.remove();manifesto.classList.remove('nr-layout-gallery3');manifesto.classList.add('nr-layout-manifesto');manifesto.id='folio-manifesto';block.html=normalize(manifesto.outerHTML);
