  const managed=Array.isArray(page.imageNodeSlots)?page.imageNodeSlots.filter(slot=>slot.startsWith(block.id+':')):[];page.imageNodeSlots=(page.imageNodeSlots||[]).filter(slot=>!managed.includes(slot));child.imageNodeSlots=managed.map(slot=>projectBlock.id+slot.slice(block.id.length));
  for(const node of project.imageNodes||[])for(const target of node.targets||[])if(target.page===page.id&&target.slot.startsWith(block.id+':')){target.page=child.id;target.slot=projectBlock.id+target.slot.slice(block.id.length)}
