document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#add-menu').hidden){e.preventDefault();closeAddMenu();return}if(e.target.matches('input,textarea,select,[contenteditable]'))return;if((e.key==='Delete'||e.key==='Backspace')&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!e.shiftKey){if(e.target.closest?.('.navigation-endpoint,.sequence-endpoint,.css-endpoint,.image-endpoint,.css-node,.image-node'))return;const page=current();if(page){e.preventDefault();deleteSectionNode(page)}return}if(e.shiftKey&&e.key.toLowerCase()==='a'){e.preventDefault();const board=boardAt(lastPointer.x,lastPointer.y),scene=$('#scene').getBoundingClientRect();openAddMenu({clientX:lastPointer.x,clientY:lastPointer.y,pageId:board?.dataset.page||null,position:board?null:{x:(lastPointer.x-scene.left)/zoom,y:(lastPointer.y-scene.top)/zoom}});return}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();$('#save').click()}if(e.key==='Escape'){selection=null;renderPanels();drawConnections()}});
// Space/middle-drag pans the workspace; wheel/trackpad zooms around the pointer.
function setZoomAt(nextZoom,clientX,clientY){
 const r=$('#workspace').getBoundingClientRect(),next=Math.max(.01,Math.min(1.1,nextZoom));
 camera=anchoredCamera(camera,{x:clientX-r.left,y:clientY-r.top},zoom,next);zoom=next;applyZoom();
}
function zoomFromWheel(deltaY,deltaMode,clientX,clientY){setZoomAt(wheelZoom(zoom,deltaY,deltaMode),clientX,clientY)}
let space=false;document.addEventListener('keydown',e=>{if(e.code==='Space'&&!e.target.matches('input,textarea,select')){space=true;e.preventDefault()}});document.addEventListener('keyup',e=>{if(e.code==='Space')space=false});window.addEventListener('blur',()=>space=false);
$('#workspace').addEventListener('wheel',e=>{if(e.target.closest('#mini-preview')||e.buttons)return;e.preventDefault();zoomFromWheel(e.deltaY,e.deltaMode,e.clientX,e.clientY)},{passive:false});
function beginCanvasPan(e){
 const middle=e.button===1,spaceLeft=space&&e.button===0;if((!middle&&!spaceLeft)||e.target.closest('#mini-preview'))return;
 e.preventDefault();e.stopPropagation();e.stopImmediatePropagation?.();const w=$('#workspace'),x=e.clientX,y=e.clientY,left=camera.x,top=camera.y,mask=middle?4:1;w.classList.add('canvas-panning');try{w.setPointerCapture(e.pointerId)}catch{}
 const end=()=>{w.classList.remove('canvas-panning');w.removeEventListener('pointermove',move,true);w.removeEventListener('pointerup',end,true);w.removeEventListener('pointercancel',end,true);try{w.releasePointerCapture(e.pointerId)}catch{}};
 const move=ev=>{if(!(ev.buttons&mask)){end();return}ev.preventDefault();camera.x=left+(ev.clientX-x);camera.y=top+(ev.clientY-y);applyZoom()};
 w.addEventListener('pointermove',move,true);w.addEventListener('pointerup',end,true);w.addEventListener('pointercancel',end,true);
}
$('#workspace').addEventListener('pointerdown',beginCanvasPan,true);


async function floatingProject(){const pages=[];for(let i=0;i<catalog.blocks.length;i++){const def=catalog.blocks[i],page=await makePage(null,i);page.name=def.name.slice(0,64);page.slug=def.id;page.hidden=false;page.blocks=[await instance(def.id)];pages.push(page)}return{version:VERSION,name:'Biblioteca · Seções flutuantes',home:pages[0].id,pages,links:[],sequences:[]}}
$('#all-blocks')?.addEventListener('click',async()=>{try{const next=await floatingProject();commit(()=>{project=next;separateEmbeddedHeaders(project,catalog,uid);migrateToSectionNodes();migrateFolioManifestoProjects();active=project.home;selection=null});focusPage()}catch(e){notify(e.message)}});

async function start(){
 initTheme();
 if(location.protocol==='file:')throw Error('Execute npm run dev e abra http://localhost:4173. O editor também funciona no GitHub Pages.');
 [catalog,imageUpgrades,textUpgrades]=await Promise.all(['catalog.json','assets/image-upgrades.json','assets/text-upgrades.json'].map(async path=>(await request(path)).json()));$('#source').innerHTML='<option value="">Todas as referências</option>'+[...new Set(catalog.blocks.map(b=>b.source))].sort((a,b)=>a.localeCompare(b)).map(source=>`<option value="${esc(source)}">${esc(source)}</option>`).join('');$('#block-count').textContent=catalog.blocks.length;
 let saved=null;try{saved=localStorage.getItem(STORAGE)}catch{}if(saved){try{project=validateProject(JSON.parse(saved),new Set(catalog.blocks.map(b=>b.id)));project.pages.forEach(p=>p.blocks.forEach(b=>b.html=normalize(b.html)))}catch{notify('Não foi possível restaurar o rascunho. Abra o JSON salvo para recuperar o projeto.')}}
 if(!project)project=await floatingProject();
 if(!project.catalogUpgrades?.includes('footers-v1')){
  const existing=new Set(project.pages.flatMap(p=>p.blocks.map(b=>b.blockId)));const missing=catalog.blocks.filter(b=>b.category==='footer'&&!existing.has(b.id));
  const baseY=Math.max(130,...project.pages.map(p=>p.y))+2600;
  for(let i=0;i<missing.length;i++){const def=missing[i],page=await makePage(null,i);page.name=def.name;page.slug=uniqueSlug(def.id);page.x=540+i*2300;page.y=baseY;page.blocks=[await instance(def.id)];project.pages.push(page)}
  project.catalogUpgrades=[...(project.catalogUpgrades||[]),'footers-v1'];
 }
 if(!project.layoutVersion){organize();project.layoutVersion=1}if(!project.catalogUpgrades?.includes('references-20261020')){
 const existing=new Set(project.pages.flatMap(p=>p.blocks.map(b=>b.blockId)));
 for(const def of catalog.blocks.filter(b=>b.id.startsWith('r20-')&&!existing.has(b.id))){if(project.pages.length>=120){notify('Biblioteca atualizada. Use Blocos para inserir as novas seções.');break}const page=await makePage(null,project.pages.length);page.name=def.name;page.slug=uniqueSlug(def.id);page.blocks=[await instance(def.id)];project.pages.push(page)}
 project.catalogUpgrades=[...(project.catalogUpgrades||[]),'references-20261020'];organize();
 }
 if(!project.uiMigrations?.includes('canvas-nodes-v1')){project.pages.forEach(p=>p.hidden=false);project.uiMigrations=[...(project.uiMigrations||[]),'canvas-nodes-v1']}
 separateEmbeddedHeaders(project,catalog,uid);migrateToSectionNodes();migrateFolioManifestoProjects();migrateImageNodeColumns();
 if(!project.uiMigrations?.includes('prototype-viewer-explicit-v2')){if(project.prototypeViewer===undefined)project.prototypeViewer=null;delete project.prototypeOutputX;delete project.prototypeOutputY;project.uiMigrations=[...(project.uiMigrations||[]),'prototype-viewer-explicit-v2']}project.prototypeOutput=project.prototypeViewer&&project.pages.some(p=>p.id===project.prototypeOutput)?project.prototypeOutput:null;for(const node of project.styleNodes||[])ensureStyleAPI(node);active=project.home;render();renderLibrary();persist();
}
start().catch(e=>{notify(e.message);$('#save-status').textContent='Não foi possível iniciar';$('#inspector').textContent=e.message});

