function organize(){
 const ordered=[...project.pages].sort((a,b)=>(definition(a.blocks[0]?.blockId)?.source||'').localeCompare(definition(b.blocks[0]?.blockId)?.source||''));
 const cols=4,rows=Array(cols).fill(130);ordered.forEach((p,i)=>{const col=i%cols,count=groupImageNodes(project,p.id).length,imageHeight=count?IMAGE_NODE_LAYOUT.topOffset+count*(IMAGE_NODE_LAYOUT.height+IMAGE_NODE_LAYOUT.gap):0;p.hidden=false;p.x=540+col*2300;p.y=rows[col];rows[col]+=Math.max(1000,metrics.get(p.id)?.height||p.blocks.length*1400,imageHeight)+400});alignAllImageNodes(project);
}
