function resizeFullPreview(){const viewport=$('#full-preview-viewport');if(!viewport||!$('#preview-dialog').open)return;const frame=$('#preview-frame'),width=previewMobile?390:1440,scale=Math.min(1,viewport.clientWidth/width);frame.style.width=width+'px';frame.style.height=Math.max(1,viewport.clientHeight/scale)+'px';frame.style.transform=`scale(${scale})`;frame.style.left=Math.max(0,(viewport.clientWidth-width*scale)/2)+'px'}
